function isSearchTree(root) {
  const stack = root ? [[root, -Infinity, Infinity]] : []
  while (stack.length) {
    const [node, low, high] = stack.pop()
    if (node.val <= low || node.val >= high) return false
    if (node.left) stack.push([node.left, low, node.val])
    if (node.right) stack.push([node.right, node.val, high])
  }
  return true
}

